const CATS_BIOLOGIE  = ["vie_bio","cellule_bio","molec_bio","genet_bio","evol_bio","classif_bio","micro_bio","plantes_bio","animaux_bio","ecol_bio","biotech_bio","figures_bio"];
const CATS_PHYSIQUE  = ["bases_py","meca_py","energie_py","thermo_py","fluides_py","ondes_py","optique_py","elec_py","relat_py","quant_py","noyau_py","figures_py"];
const CATS_VOYAGE    = ["prepa_vo","papiers_vo","argent_vo","transport_vo","hebergement_vo","sante_vo","culture_vo","terrain_vo","tourisme_vo","geo_vo"];
const CATS_CHIMIE    = ["matiere_ch","tableau_ch","liaisons_ch","reactions_ch","solutions_ch","thermo_ch","organique_ch","analyse_ch","materiaux_ch","industrie_ch","histoire_ch"];
const CATS_RELIGIONS = ["fait_re","croyances_re","textes_re","rites_re","institutions_re","abrahamiques_re","orientales_re","autres_re","secularisation_re","etude_re"];
const CATS_MUSIQUE   = ["bases_mu","hauteur_mu","harmonie_mu","rythme_mu","forme_mu","instruments_mu","acoustique_mu","studio_mu","genres_mu","histoire_mu","metier_mu"];
const CATS_AUTOMOBILE = ["bases_au","moteur_au","transmission_au","chassis_au","securite_au","elec_au","electrique_au","entretien_au","conduite_au","admin_au","histoire_au"];
const CATS_BUREAU    = ["bases_bu","texte_bu","tableur_bu","presentation_bu","fichiers_bu","messagerie_bu","collab_bu","notes_bu","methodes_bu"];
const CATS_THAI      = ["geo_th","histoire_th","langue_th","religion_th","cuisine_th","societe_th","pratique_th","eco_th"];
const CATS_MATHS     = ["nombres","algebre","geometrie","analyse_math","probas","logique"];
const CATS_SPORT     = ["effort","methodes","blessures","nutrition","sports","competition"];
const CATS_PSYCHO    = ["courants","cognition","biais","developpement","troubles","therapies","social"];
const CATS_HABITAT   = ["structure","isolation","chauffage","elec_maison","plomberie","outillage","fixations","finitions","materiaux","menuiseries","projet"];
const CATS_FRANCAIS  = ["histoire","grammaire","conjugaison","orthographe","vocabulaire","figures_style","rhetorique","textes","oral","usage"];
const CATS_ELECTRO   = ["electricite","composants","circuits","signaux","processeurs","memoires","ordinateur","connectique","makers","peripheriques"];
const CATS_CUISINE   = ["bases","gestes","cuissons","sauces","produits","saveurs","patisserie","boissons","alimentation","restauration","histoire"];
const CATS_ECO       = ["fondements","monnaie","emploi","etat","compta","perso","bourse","commerce","ecoles"];
const CATS_IA        = ["fondements","modeles","entrainement","generatif","nlp","vision","agents","alignement","ecosysteme"];
